Using a change of variables and the periodicity of $V_{\rm per}$, by \eqref{tre-b}  with $s_1=a/\varepsilon$ and $s_2=b/\varepsilon$ we obtain
\begin{eqnarray*}
\limsup_{\varepsilon\to0} F_\varepsilon(v_\varepsilon,\mathcal F^\varepsilon_t,B^\varepsilon_t; (a,b))
&=& \limsup_{\varepsilon\to0}\varepsilon\, \mathbb E\Big(\int_{a/\varepsilon}^{b/\varepsilon} \Big(\frac12|\dot{w}{}^\xi(t)|^2+V_{\rm per}(B^\xi_t+ w^\xi(t))\Big)dt\Big)\\
&\le&{
(b-a)\Big( f_{\rm hom}(\xi)+\eta +\Big(3\frac{K}T+{2}\eta_K\Big)\max|V_{\rm per}|\Big)},
\end{eqnarray*}
and the claim

\label{concat}
 Consider $B^1_t$, $B^2_t$ two Brownian motions, valued in~${\mathbb R}^d$, adapted to two independent filtrations $\mathcal F^1_t$ and  $\mathcal F^2_t$,  and let $\tau$ be a stopping time for the filtration $\mathcal F^1_t$. Then the process
\begin{equation}
\widetilde{B}_t\,=\,\left\{
\begin{array}{cc}
B^1_t&\text{when}\quad t\leq\tau,  \\
 B^2_{t-\tau}\,+\,B^1_{\tau} &  \text{when}\quad t\geq\tau,
\end{array}
\right.
\end{equation}
is a Brownian motion, adapted to the filtration $\widetilde{\mathcal F}_t:=\sigma(\mathcal F^1_t,\mathcal F^2_t)$.

We are going to use a \emph{coupling method}. For this purpose, we first  introduce the concatenation mapping 
$F\colon \big(C\big({\mathbb R}_+,{\mathbb R}^d\big)\times{\mathbb R}_+\big)\times C_0\big({\mathbb R}_+,{\mathbb R}^d\big)\to C\big({\mathbb R}_+,{\mathbb R}^d\big)$,
where $C_0$ denotes continuous functions with value $0$ in $0$, defined by 
\begin{equation}
\label{eq:F}
F ((a,T),b) (t)\,
=\,\left\{
\begin{array}{cc}
a(t) &  \text{when} \quad t\,\leq \,T,  \\
b(t-T)\,+\,a(T) &  \text{when} \quad t\,\geq\,T.
\end{array}
\right.
\end{equation}
This function is deterministic, measurable and actually continuous. 
Note that $\widetilde{B}_t=F((B^1_t,\tau),B^2_t)$; that is, for $P$-almost every $\omega\in\Omega$ we have $\widetilde{B}_t(\omega)=F((B^1(\omega),\tau(\omega)) ,B^2(\omega))(t)$, where 
$B^i(\omega)(t)=B^i_t(\omega)$. From this, we can deduce that $\widetilde B_t$ is 
adapted to $\widetilde{\mathcal F}_t$. Note moreover that $\tau$ is also a stopping time for  $\widetilde{\mathcal F}_t$
\medskip

Let  $\{U_t\}_{t\ge 0}$ be the stochastic process with values in $(\mathbb R^d\times{\mathbb R}_+)\times \mathbb R^d$ defined by the pair

\begin{equation}
\label{eq:Ut}
U_t\,=\,\big((\widetilde B_{t \wedge\tau},\tau), \widetilde B_{t+\tau}-\widetilde B_{\tau}\big),
\end{equation}
and let $\{V_t\}_{t\ge 0}$ be the stochastic process with values in $(\mathbb R^d\times{\mathbb R}_+)\times \mathbb R^d$ defined by the pair
\begin{equation}
\label{eq:Vt}
V_t\,=\,\big((B^1_{t \wedge\tau},\tau), B^1_{t+\tau}- B^1_{\tau}\big).
\end{equation}
By well-known properties of the Brownian motions, the trajectories of $U_t$ and $V_t$  are almost surely elements of the functional space~$C\big({\mathbb R}_+,{\mathbb R}^d\times{\mathbb R}^d\big)$. Therefore, the stochastic processes $U_t$ and $V_t$ define two random functions with values in $\big(C\big({\mathbb R}_+,{\mathbb R}^d\big)\times{\mathbb R}_+\big)\times C\big({\mathbb R}_+,{\mathbb R}^d\big)$ denoted by $U$ and $V$.


Our claim $U_t\buildrel{\mathcal L}\over\sim V_t$ follows from the following three properties:

\smallskip
(i) $U_t$ also writes as
\begin{equation}
\label{eq:Ut-bis}
U_t\,=\big((B^1_{t \wedge\tau},\tau), B^2_t\big),\end{equation}
 respectively by definition of the first argument and because the second argument writes as
$\widetilde B_{t+\tau}-\widetilde B_{\tau} \,=\,(B^2_{t}\,+\,B^1_{\tau})-\,B^1_{\tau}\,=\,B^2_t$;

\smallskip(ii) by the strong Markov property, the second argument of $V_t$ is a Brownian motion~$W_t$, independent from $(B^1_{t\wedge\tau},\tau)$, so that
\begin{equation}
\label{eq:Vt-bis}
V_t\,=\, ((B^1_{t\wedge\tau},\tau), W_t);
\end{equation}


\smallskip (iii) the two arguments within each pair are independent from one another, so the joint law of each pair is the product of the laws of the arguments. Moreover, for every finite family $0\le t_1\le\cdots\le t_M$ by a similar argument we can see that the joint law in $\big((\mathbb R^d\times{\mathbb R}_+)\times \mathbb R^d\big)^M$ of 
$(U_{t_1},\ldots, U_{t_M})$ is the same as  the joint law  of $(V_{t_1},\ldots, V_{t_M})$.

\smallskip

We then deduce that the random maps $U$ and $V$ have the same law in $\big(C\big({\mathbb R}_+,{\mathbb R}^d\big)\times{\mathbb R}_+\big)\times C\big({\mathbb R}_+,{\mathbb R}^d\big)$.

\medskip

We finally remark that, since the concatenation mapping~$F$ is deterministic and continuous, the maps $F(U)$ and $F(V)$ have the same law in $C\big({\mathbb R}_+,{\mathbb R}^d\big)$. Since 
$$ \widetilde B \,=\,F(U)\quad \text{and}\quad B^1\,=\,F(V),$$
where $ \widetilde B $ and $B^1$ denote the continuous functions $t\mapsto  \widetilde B_t$ and $t\mapsto  B^1_t$, respectively, we conclude that $ \widetilde B$ and $ B^1$ have the same law in $C\big({\mathbb R}_+,{\mathbb R}^d\big)$. This implies that $\widetilde B$ is a Brownian motion.

The issue is related to the capacity of the ball on the periodic torus. 
We let $W_t$, with $W_0=0$, denote the projection of the Brownian motion $B_t$ onto the torus $\mathbb{T}^d =
\mathbb{R}^d / \mathbb{Z}^d$. 

We first fix a closed ball $E_r\subset \mathbb{T}^d$ of radius $r>0$ and, for $x\in E_r^c:=\mathbb{T}^d\setminus E$, we let
\begin{equation}
\label{eq:Appendix-tau}
\tau_x := \inf \{ t \geq 0 : x\,+\,W_t \in E_r \}
\end{equation}
denote the first time at which the Brownian enters $E_r$, which is a stopping time for the filtration generated by the Brownian. A simple application of the Feynman-Kac representation formula for a steady-state elliptic equation, with homogeneous Dirichlet boundary conditions on~$\partial E_r$ and periodic conditions on the torus, implies that the function~$u(x)=\mathbb{E}[\tau_x]$ solves on~$\mathbb{T}^d$ the equation
$$
\begin{cases}
-\frac{1}{2} \Delta u = 1 & x\in E_r^c, \\
u = 0 & x \in E_r.
\end{cases}
$$
We then have

(a) the solution~$u$ is bounded and we may define 
$U_r := \sup\limits_{x \in \mathbb{T}^d} u(x) < \infty$;

(b) this bound only depends on the ambient dimension~$d$ and the radius~$r$ of the ball~$E$. 

\smallskip
In the following we use the shorthand $\{\tau_x > T_0\}$ for $\{\omega\in\Omega: \tau_x(\omega) > T_0\}$, and similar notation, for subsets of $\Omega$.

\smallskip
For any time $T_0$, we have 
$u(x)\,=\,\mathbb{E}[\tau_x]\,\geq\,T_0\,
{P}(\{\tau_x > T_0\})$,
so that, upon taking the supremum over~$x \in \mathbb{T}^d$, and noting that 
$
P(\{\tau_x > T_0\}) = {P}(
\{ x\,+\,W_t \in E_r^c\ \hbox{ for all } t \in [0,T_0]\})$,
we obtain
\begin{equation}
\label{eq:Appendix-sup}
 \sup_{x \in \mathbb{T}^d}P(
 \{ x\,+\,W_t \in E_r^c\ \hbox{ for all } t \in [0,T_0]\})\leq \frac{U_r}{T_0}.
\end{equation}
Using the Markov property of the Brownian motion, we now iterate formula~\eqref{eq:Appendix-sup}. To this end, we indeed observe that the probability of not entering the ball~$E_r$ in, say, an interval of length
$2\,T_0$ is smaller than that of not entering it in the first
interval $[0,T_0]$, and then of still not entering~$E_r$ in $[T_0,2\,T_0]$ provided that
we take the sup of the latter over all the positions of the process at time $T_0$. Mathematically, this intuition amounts to the following observations. We first remark that 
\begin{eqnarray}
\label{eq:Appendix-1}
&&P(\{ x+W_t \in E_r^c \hbox{ for all }   t \in [0,2\,T_0]\})\nonumber\\
&&=P(\{x+W_t \in E_r^c  \hbox{ for all }  t \in [0,T_0]\}\cap
\{ x+W_t \in E_r^c\hbox{ for all }  t \in [T_0,2\,T_0]\})\nonumber\\
&&=P(\{x+W_t \in E_r^c  \hbox{ for all }  t \in [0,T_0]\}\nonumber\\
&&\hskip 1truecm\cap\{ x+W_{T_0}+(W_{s+T_0}-W_{T_0}) \in E_r^c \hbox{ for all }  s \in [0,T_0]\}).
\end{eqnarray}
We focus on the latter event
\begin{equation*}
A_2:=\{ x +W_{T_0}+(W_{s+T_0}-W_{T_0}) \in E_r^c  \hbox{ for all }  s \in [0,T_0]\}.
\end{equation*}
Using the Markov property, the increment~$W_{s+T_0}-W_{T_0}$ is a Brownian motion, which is denoted by~$\widetilde{W_s}$, that is independent from the original Brownian motion~$W_t$ on~$[0,T_0]$ and thus of the event \begin{equation*}
 A_1:=\{x+W_t \in E_r^c  \hbox{ for all }  t \in [0,T_0]\}.
 \end{equation*}
  In addition, writing the event
 \begin{equation*}
  A_2=\big\{ x+W_{T_0}+\widetilde{W_s} \in E_r^c\ \hbox{ for all }  s \in [0,T_0]\},
  \end{equation*}
again by the Markov property, we note that $A_2$ depends on the event $A_1$ through the position $y=x+W_{T_0}$. 

We therefore have 
\begin{equation}
\label{eq:Appendix-2}
P (A_1\cap A_2)= P (A_1)P (A_2| A_1)=P(A_1) P (A_2| x+W_{T_0} ).
\end{equation}
Now we have
\begin{eqnarray}
\label{eq:Appendix-3}
P (A_2| x\,+\,W_{T_0})
\leq\sup_{y\in{\mathbb T}^d}P(\{y+\widetilde{W_s} \in E_r^c \hbox{ for all }  s\in [0,T_0]\}).
\end{eqnarray}
Collecting~\eqref{eq:Appendix-1}, \eqref{eq:Appendix-2} and \eqref{eq:Appendix-3}, we obtain
\begin{eqnarray}
\label{eq:Appendix-4}
&&\hskip-1cm P( \{x+W_t \in E_r^c \hbox{ for all } t \in [0,2\,T_0]\})\leq P ( x+W_t \in E_r^c  \hbox{ for all } t \in [0,T_0]\})\times\nonumber\\
&&\hskip3cm\times \sup_{y\in{\mathbb T}^d} P \big(\{y+\widetilde{W_s} \in E_r^c\, \hbox{ for all }  s \in [0,T_0]\}\big).
\end{eqnarray}
Using~\eqref{eq:Appendix-sup} for each of the two factors in the right-hand side of \eqref{eq:Appendix-4}, we have
\begin{equation*}
 \sup_{x \in \mathbb{T}^d} P(\{ x +W_t \in E_r^c\ \hbox{ for all } t \in [0,2T_0]\})\leq \Big(\frac{U_r}{T_0}\Big)^2.
\end{equation*}
An iteration of this argument gives
\begin{equation}
\label{eq:Appendix-sup-k}
 \sup_{x \in \mathbb{T}^d}P(\{ x +W_t \in E_r^c\ \hbox{ for all } t \in [0,kT_0]\})\leq \Big(\frac{U_r}{T_0}\Big)^{k}.
\end{equation}
We finally consider an arbitrary time~$T$, which we may always assume larger than $2\,U_r$ since we are interested in the behavior of~$P(\{ x +W_t \in E_r^c\ \hbox{ for all } t \in [0,T]\})$ for $T$ large. Choosing $T_0=2\,U_r$ and iterating $k$ times where $k$ is the integer part~$ k\,=\,\lfloor\frac{T}{T_0}\rfloor$,  by~\eqref{eq:Appendix-sup-k} we obtain
\begin{equation*}
 \sup_{x \in \mathbb{T}^d}P( \{x+W_t \in E_r^c\, \hbox{ for all } t \in [0,k\,T_0]\})\leq \Big(\frac12\Big)^{\left\lfloor\frac{T}{T_0}\right\rfloor}\,\leq \, \Big(\frac12\Big)^{\frac{T}{T_0}-1},
\end{equation*}
thus, since $kT_0=\lfloor\frac{T}{T_0}\rfloor\,T_0\leq T$, that, \emph{a fortiori},
\begin{equation*}
 \sup_{x \in \mathbb{T}^d}P(\{x +W_t \in E_r^c\, \hbox{ for all } t \in [0,T]\})\,\leq \, \Big(\frac12\Big)^{\frac{T}{T_0}-1}.
\end{equation*}
It follows that 
\begin{equation}
\label{eq:Appendix-sup-exp}
 \sup_{x \in \mathbb{T}^d} P( \{x+W_t \in E_r^c\ \hbox{ for all } t \in [0,T]\})\,\leq \,2\,\exp{(-\lambda \,T)}
\end{equation}
for, say, the positive constant~$\lambda\,=\,\frac{1}{2\,U_r}\log{2}$. An optimal constant (the actual exponential rate) may be determined but~\eqref{eq:Appendix-sup-exp} is sufficient for our purposes in the main body of the text: the probability~$P( \{x+W_t \in E_r^c\ \hbox{ for all } t \in [0,T]\})$ is, uniformly in~$x\in{\mathbb T}^d$, getting exponentially small as time grows. This concludes the proof of our claim.
